#pragma once

#include <span>
#include <string_view>

namespace xlang {

/// One file of the standard library compiled into the compiler (`std/**/*.xl`).
struct EmbeddedFile {
    std::string_view path;    ///< relative to the stdlib root, e.g. `mem.xl`, `sys/linux.xl`
    std::string_view content; ///< raw source bytes
};

/// Every embedded stdlib file, generated by `xmake/compiler.lua` (build/gen/std_blob.cpp).
[[nodiscard]] std::span<const EmbeddedFile> embeddedStd() noexcept;

} // namespace xlang
